def resolve_alias(vocabulary: str, text: str) -> str | None:
    """Return the value code for a code or alias (case-insensitive), or None."""
    needle = text.strip().lower()
    for code in LABELS[vocabulary]:
        if code.lower() == needle:
            return code
    for alias, code in ALIASES.get(vocabulary, {}).items():
        if alias.lower() == needle:
            return code
    return None


def attribute(vocabulary: str, code: str, key: str) -> Any:
    """Typed attribute of a vocabulary value."""
    return ATTRIBUTES[vocabulary][code][key]
